#pragma once

#include <vector>

// One drawable/interactive item on the front panel, in reference-photo pixels
// (2191 x 1117, lens- and parallax-corrected). Generated by tools/measure_panel.py.
struct PanelElement
{
    enum Type { knob, button, led, fader, text, arrow, bracket, display, frame };

    Type type;
    const char* id;
    float x, y;    // centre (knob/button/led), top-centre (fader), anchor (text), left/top (display, bracket)
    float x1, y1;  // second corner (display, frame), bottom (fader), right end (bracket)
    float w, h;    // button size, or font size for text
    const char* label;
    // Binding: "param_id", "a@sel=0|b@sel=1" (which param depends on a selector),
    // "cycle:param" (button steps a selector), "menu:Name", "action:name", "ui:name".
    const char* bind;
    int value;     // LED: selector value that lights it
    bool flag;     // knob: big; text: bold
    const char* style; // button style, text alignment, or frame shape ("u" open top, "left" [ bracket)
};

struct PanelLayout
{
    struct Rule { float x0, y, x1; };

    float panel[4]; // face rectangle: x0, y0, x1, y1
    std::vector<Rule> rules;
    std::vector<PanelElement> elements;

    static const PanelLayout& get();
};
